{
  "packet_id": "H6-T01-2",
  "claim_id": "C060",
  "status": "SUPPORTED",
  "claim": {
    "component_id": "C060.component",
    "value": "If agreed service limits are exceeded, the trial must be stopped or reversed.",
    "scope": "Service trigger for trial termination or reversal; the limits and response-selection rule are unspecified.",
    "provenance": {
      "refs": [
        {
          "source_id": "P031",
          "role": "SUPPORT"
        }
      ],
      "support_status": "SUFFICIENT",
      "rationale": "P031 explicitly prescribes stopping or reversing the trial upon exceeding agreed service limits."
    }
  },
  "signal_basis": {
    "component_id": "C060.signal_basis",
    "value": "Reduction tests produce a smaller configuration that repeatedly reproduces lateness while specified further removals do not. Subsequent trial monitoring tracks service-relevant outcomes, and exceeding agreed service limits is an explicit stopping-or-reversal trigger.",
    "scope": "The reduction signal supports investigation; the service-limit trigger governs continuation of the subsequent field trial and does not assert that a breach has occurred.",
    "provenance": {
      "refs": [
        {
          "source_id": "P018",
          "role": "SUPPORT"
        },
        {
          "source_id": "P030",
          "role": "SUPPORT"
        },
        {
          "source_id": "P031",
          "role": "SUPPORT"
        }
      ],
      "support_status": "SUFFICIENT",
      "rationale": "These spans supply the reduction observation, trial monitoring requirements, and conditional service-limit response."
    }
  },
  "stated_empirical_relation": {
    "component_id": "C060.stated_empirical_relation",
    "value": "NOT_APPLICABLE",
    "scope": "NOT_APPLICABLE",
    "provenance": {
      "refs": [],
      "support_status": "SUFFICIENT",
      "rationale": "This is an explicit operational guardrail, with no unresolved empirical relation needed to license the conditional rule."
    }
  },
  "rationale": "The claim is licensed as a constraint on the bounded trial. Applying the agreed service limits warrants stopping or reversal upon breach; the reduction signal need not establish an empirical benefit from that response. The claim does not assert that a breach occurred or that reversal will restore service.",
  "uncertainty": "The mapping does not specify the service thresholds or how to choose between stopping and reversal, so it cannot determine a particular intervention from concrete trial measurements.",
  "anomalies": []
}
